import{_ as e,o as t,c as r,a5 as i}from"./chunks/framework.CXvGqWf0.js";const u=JSON.parse('{"title":"漫画 · 第 71 话 CSS/HTML 反例库","description":"","frontmatter":{},"headers":[],"relativePath":"comics/practice/EP.71-antipatterns.md","filePath":"comics/practice/EP.71-antipatterns.md","lastUpdated":1793853676000}'),o={name:"comics/practice/EP.71-antipatterns.md"};function l(n,a,s,c,d,h){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="漫画-·-第-71-话-css-html-反例库" tabindex="-1">漫画 · 第 71 话 CSS/HTML 反例库 <a class="header-anchor" href="#漫画-·-第-71-话-css-html-反例库" aria-label="Permalink to &quot;漫画 · 第 71 话 CSS/HTML 反例库&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/practice/01-antipatterns">docs/practice/01-antipatterns.md</a> ｜ 原画：<a href="./EP.71-antipatterns.svg">EP.71-antipatterns.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师。本话她把自己半年踩过的坑整理成一张清单，却发现只写「不要这样」没人记得住。</li><li><strong>码叔</strong>：老工程师。他要求每条反例都补上「触发了哪条机制、会导致什么后果」。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>清单从 8 条扩到 30 条，按语义、布局、层叠、视觉、性能、工程六类归档。团队评审时不再说「感觉不对」，而是直接指出「这里 <code>min-width:auto</code> 会撑破」或「这里 <code>margin</code> 会折叠」。修复按影响面排序，一周内解决 9 个高优先级项。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>反例如果只写结论，读者只会记住「不要用 div 当按钮」，遇到「用 span 当按钮」仍然会犯。错误往往由多个机制叠加：固定高度裁剪、Flex 子项不收缩、绝对定位找不到祖先，都是「能用但会坏」。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p>把 30 条按三类归因：语义错误换原生元素；机制误用要理解包含块、格式化上下文、层叠顺序；工程债用令牌、层、预算与测试治理。每条都写成「错法 → 修法 → 机制」，评审时能直接对照。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>团队按「影响用户数 × 修复成本」排序：先修假按钮、焦点轮廓与对比度，再修 Flex 撑破与布局抖动，最后把 <code>z-index</code> 与魔法数字交给架构篇的令牌与层叠改造。示例里 10 条高发项左右并排，可直接看到焦点、裁剪、溢出与动效差异。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>反例的价值在机制归因，不在背结论。</li><li>先修影响用户的：语义与可访问性优先于代码风格。</li><li>一次只改一类，语义、布局、性能分开提交。</li><li>把高频反例固化成 lint 规则与审计脚本，比记忆可靠。</li><li>修复必须配可复现的前后对比或测试。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：为什么「用 <code>div</code> 当按钮」比「按钮样式写得不好看」更严重？</p><p><strong>答</strong>：样式不好看只影响观感，假按钮会同时破坏读屏与键盘两条路径：读屏拿不到按钮角色，键盘无法聚焦，回车空格也不触发。它让一部分用户<strong>无法完成任务</strong>，而不只是体验差。修复成本又很低——换成原生 <code>button</code> 即可。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>在示例中按类别筛选，逐条对比错误版与修复版：<a href="./../../examples/practice/01-antipatterns">examples/practice/01-antipatterns</a></li><li>用 Tab 键在「假按钮」与「原生按钮」之间移动，观察能否聚焦。</li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>第 72 话《分级自测题库》——「都见过」不等于「掌握了」，用三级题目把盲区找出来。</p>',22)])])}const m=e(o,[["render",l]]);export{u as __pageData,m as default};
